'use client';
import { useState } from 'react';
import axios from 'axios';

export default function Home() {
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [isAffectationDone, setIsAffectationDone] = useState(false);

  const handleAffectation = async () => {
    if (isAffectationDone) {
      setError('L\'affectation a déjà été réalisée.');
      return;
    }

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const response = await axios.post('http://localhost:5000/api/affectation', {}, {
        headers: {
          'Content-Type': 'application/json',
        },
      });

      setResult(response.data);
      setIsAffectationDone(true); // Marquer l'affectation comme réalisée
    } catch (err) {
      setError(err.message || 'Erreur lors de l\'affectation');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-gray-100">
    <Sidebar className="hidden lg:block bg-blue-700 text-white p-4 w-64 shadow-lg" />

    <div className="flex flex-col w-full bg-gray-50">
      <Navbar className="bg-blue-600 text-white p-4 shadow-md" />

    <div className="p-5 font-sans max-w-4xl mx-auto bg-gray-50 rounded-lg shadow-md transition-all">
      <h1 className="text-center text-3xl text-gray-800 font-bold mb-6">
        Affectation Aléatoire des Tuteurs et Sujets
      </h1>
      <button
        onClick={handleAffectation}
        disabled={loading || isAffectationDone}
        className={`block mx-auto px-6 py-3 text-lg ${
          loading || isAffectationDone ? 'bg-gray-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700'
        } text-white rounded-lg shadow-md transition-all`}
      >
        {loading ? 'Chargement...' : isAffectationDone ? 'Affectation déjà réalisée' : 'Lancer l\'affectation'}
      </button>

     

      {error && <p className="text-red-500 text-center mt-4">{error}</p>}

      {result && (
        <div className="mt-8 p-6 bg-white rounded-lg shadow-md">
          <h2 className="text-center text-2xl text-blue-600 font-semibold mb-6">
            Résultats de l'affectation :
          </h2>
          {result.data && result.data.length > 0 ? (
            <div className="bg-blue-50 p-6 rounded-lg border border-blue-200">
              {result.data.map((groupe, index) => (
                <div
                  key={index}
                  className="mb-6 last:mb-0 p-4 bg-white rounded-lg shadow-sm hover:shadow-md transition-all"
                >
                  <h3 className="text-xl text-blue-600 font-semibold mb-3">
                    {groupe.groupeNom}
                  </h3>
                  <div className="space-y-2">
                    <p>
                      <strong>Tuteur :</strong>{' '}
                      {groupe.tuteurNom ? `${groupe.tuteurNom}` : 'Non assigné'}
                    </p>
                    <p>
                      <strong>Sujet :</strong> {groupe.sujetTitre}
                    </p>
                    <p>
                      <strong>Étudiants :</strong>
                    </p>
                    <ul className="pl-4">
                      {groupe.etudiants.map((etudiant, i) => (
                        <li key={i} className="text-gray-700">
                          {etudiant}
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-gray-600 text-center">Aucun groupe disponible.</p>
          )}
        </div>
      )}
    </div>
    </div>
    </div>
  );
}